import Foundation
@testable import SidebarKit
import SidebarProtocol
import Testing

struct AeroSpaceConfigEditorTests {
    static let rule = AeroSpaceConfigEditor.floatRule

    @Test func reportsConfiguredConfig() {
        let analysis = AeroSpaceConfigEditor.analyze("[gaps]\nouter.right = [{ monitor.main = 305 }, 5]\n\n\(Self.rule)\n")

        #expect(analysis == .init(missingGap: false, missingFloatRule: false, width: 300, warnings: []))
        #expect(analysis.isConfigured)
    }

    @Test func reportsMissingPiecesAndWarnings() {
        let text = """
            # Generated by a script. Do not edit.
            # \(SidebarApp.bundleIdentifier) mentioned only in a comment
            [mode.main.binding]
            alt-f = 'fullscreen --no-outer-gaps'
            """

        let analysis = AeroSpaceConfigEditor.analyze(text)

        #expect(analysis.missingGap && analysis.missingFloatRule && analysis.width == nil)
        #expect(analysis.warnings.count == 2)
        #expect(AeroSpaceConfigEditor.isGenerated(text))
    }

    @Test(arguments: [
        // Constant in [gaps], comment preserved.
        ("[gaps]\nouter.right = 5 # edge\n", "[gaps]\nouter.right = [{ monitor.main = 305 }, 5] # edge\n"),
        // Per-monitor array without a main entry.
        ("[gaps]\nouter.right = [{ monitor.secondary = 20 }, 8]\n", "[gaps]\nouter.right = [{ monitor.main = 308 }, { monitor.secondary = 20 }, 8]\n"),
        // Dotted key at the root.
        ("gaps.outer.right = 4\n[mode.main.binding]\n", "gaps.outer.right = [{ monitor.main = 304 }, 4]\n[mode.main.binding]\n"),
        // [gaps.outer] table.
        ("[gaps.outer]\nright = 2\n", "[gaps.outer]\nright = [{ monitor.main = 302 }, 2]\n"),
        // [gaps] without outer.right.
        ("[gaps]\ninner.horizontal = 10\n", "[gaps]\nouter.right = [{ monitor.main = 300 }, 0]\ninner.horizontal = 10\n"),
        // [gaps.outer] without right.
        ("[gaps.outer]\nleft = 1\n", "[gaps.outer]\nright = [{ monitor.main = 300 }, 0]\nleft = 1\n"),
        // No gaps at all: root key before the first table.
        ("start-at-login = true\n[mode.main.binding]\nalt-a = 'workspace A'\n", "start-at-login = true\ngaps.outer.right = [{ monitor.main = 300 }, 0]\n[mode.main.binding]\nalt-a = 'workspace A'\n"),
    ])
    func addsGapPreservingLayout(original: String, expectedPrefix: String) throws {
        let result = try AeroSpaceConfigEditor.apply(to: original, width: 300)

        #expect(result.hasPrefix(expectedPrefix))
        #expect(result.hasSuffix(Self.rule + "\n"))
        #expect(AeroSpaceConfigEditor.analyze(result).isConfigured)
    }

    @Test func fileWithoutTablesGetsRootGapBeforeTrailingNewline() throws {
        #expect(try AeroSpaceConfigEditor.apply(to: "start-at-login = true\n", width: 300)
            .hasPrefix("start-at-login = true\ngaps.outer.right = [{ monitor.main = 300 }, 0]\n\n"))
    }

    @Test func emptyFileGetsRootGapAndRule() throws {
        let result = try AeroSpaceConfigEditor.apply(to: "", width: 250)

        #expect(result == "gaps.outer.right = [{ monitor.main = 250 }, 0]\n\n" + Self.rule + "\n")
    }

    @Test func leavesConfiguredPartsAlone() throws {
        let configured = "[gaps]\nouter.right = [{ monitor.main = 305 }, 5]\n"

        #expect(try AeroSpaceConfigEditor.apply(to: configured, width: 300) == configured + "\n" + Self.rule + "\n")
    }

    @Test(arguments: [
        ("[gaps]\nouter.right = [\n  { monitor.secondary = 1 },\n  5,\n]\n", "spans several lines"),
        ("[gaps]\nouter.right = [{ monitor.main = 5 }, 5]\n", "already has a monitor.main entry"),
        ("[gaps]\nouter.right = [{ monitor.secondary = 20 }]\n", "does not recognize"),
        ("on-window-detected = []\n", "does not parse"),
        ("[gaps]\nouter.right = []\n", "does not recognize"),
    ])
    func refusesLayoutsItCannotEditSafely(original: String, reason: String) {
        #expect {
            try AeroSpaceConfigEditor.apply(to: original, width: 300)
        } throws: { error in
            guard case AeroSpaceConfigEditor.EditError.unsupported(let message) = error else { return false }
            return message.contains(reason)
        }
    }
}

struct AeroSpaceSetupTests {
    let home: TemporaryDirectory

    init() throws {
        home = try TemporaryDirectory()
    }

    func setup(_ cli: FakeAeroSpaceCLI = FakeAeroSpaceCLI()) -> AeroSpaceSetup {
        AeroSpaceSetup(home: home.url, environment: [:], cli: cli, now: { Date(timeIntervalSince1970: 0) })
    }

    var configURL: URL { home.url.appendingPathComponent(".config/aerospace/aerospace.toml") }

    @Test func reportsState() throws {
        #expect(setup().state() == .notFound)

        try home.write("[gaps]\nouter.left = 5\n", to: ".config/aerospace/aerospace.toml")
        guard case .ready(let analysis, let url) = setup().state() else { Issue.record("not ready"); return }
        #expect(analysis.missingGap)
        #expect(url == configURL)

        try home.write("", to: ".aerospace.toml")
        guard case .unreadable(let reason) = setup().state() else { Issue.record("not unreadable"); return }
        #expect(reason.contains("ambiguous"))
    }

    @Test func appliesValidatesAndReloads() async throws {
        try home.write("[gaps]\nouter.right = 5\n", to: ".config/aerospace/aerospace.toml")
        let cli = FakeAeroSpaceCLI()

        let outcome = try await setup(cli).apply()

        let backup = configURL.appendingPathExtension("bak-" + Self.timestamp)
        #expect(outcome == .updated(backup: backup))
        #expect(try String(contentsOf: backup, encoding: .utf8) == "[gaps]\nouter.right = 5\n")
        #expect(AeroSpaceConfigEditor.analyze(try String(contentsOf: configURL, encoding: .utf8)).isConfigured)
        #expect(cli.calls == [["reload-config", "--dry-run", "--no-gui"], ["reload-config", "--no-gui"]])
    }

    @Test func restoresOriginalWhenAeroSpaceRejectsTheEdit() async throws {
        try home.write("[gaps]\nouter.right = 5\n", to: ".config/aerospace/aerospace.toml")
        let cli = FakeAeroSpaceCLI(results: ["--dry-run": CommandResult(status: 1, output: "bad key\n")])

        await #expect(throws: AeroSpaceSetup.SetupError.rejected("bad key")) { try await setup(cli).apply() }

        #expect(try String(contentsOf: configURL, encoding: .utf8) == "[gaps]\nouter.right = 5\n")
        #expect(cli.calls.count == 1)
    }

    @Test func keepsEditWhenAeroSpaceCommandIsMissing() async throws {
        try home.write("", to: ".config/aerospace/aerospace.toml")
        let cli = FakeAeroSpaceCLI(results: ["--dry-run": CommandResult(status: 127, output: "command not found")])

        let outcome = try await setup(cli).apply()

        #expect(outcome == .updatedWithoutReload(backup: configURL.appendingPathExtension("bak-" + Self.timestamp)))
        #expect(AeroSpaceConfigEditor.analyze(try String(contentsOf: configURL, encoding: .utf8)).isConfigured)
    }

    @Test func editsSymlinkTargets() async throws {
        try home.write("", to: "dotfiles/aerospace.toml")
        try FileManager.default.createDirectory(at: configURL.deletingLastPathComponent(), withIntermediateDirectories: true)
        try FileManager.default.createSymbolicLink(at: configURL, withDestinationURL: home.url.appendingPathComponent("dotfiles/aerospace.toml"))

        _ = try await setup().apply()

        #expect(try FileManager.default.destinationOfSymbolicLink(atPath: configURL.path).hasSuffix("dotfiles/aerospace.toml"))
        #expect(AeroSpaceConfigEditor.analyze(try String(contentsOf: home.url.appendingPathComponent("dotfiles/aerospace.toml"), encoding: .utf8)).isConfigured)
    }

    @Test func refusesMissingGeneratedOrUnsupportedConfigs() async throws {
        await #expect(throws: AeroSpaceSetup.SetupError.notFound) { try await setup().apply() }

        try home.write("# Generated from base.toml\n", to: ".config/aerospace/aerospace.toml")
        await #expect(throws: AeroSpaceSetup.SetupError.generated(configURL.resolvingSymlinksInPath())) { try await setup().apply() }

        try home.write("[gaps]\nouter.right = [{ monitor.main = 1 }, 5]\n", to: ".config/aerospace/aerospace.toml")
        await #expect { try await setup().apply() } throws: { error in
            if case AeroSpaceSetup.SetupError.unsupported = error { return true }
            return false
        }

        try home.write("", to: ".aerospace.toml")
        await #expect { try await setup().apply() } throws: { error in
            if case AeroSpaceSetup.SetupError.io = error { return true }
            return false
        }
    }

    @Test func reportsUnreadableAndUnwritableConfigs() async throws {
        try home.write("x", to: ".config/aerospace/aerospace.toml")
        try FileManager.default.setAttributes([.posixPermissions: 0o000], ofItemAtPath: configURL.path)
        defer { try? FileManager.default.setAttributes([.posixPermissions: 0o644], ofItemAtPath: configURL.path) }

        await #expect { try await setup().apply() } throws: { error in
            if case AeroSpaceSetup.SetupError.io = error { return true }
            return false
        }

        try FileManager.default.setAttributes([.posixPermissions: 0o644], ofItemAtPath: configURL.path)
        try "".write(to: configURL, atomically: true, encoding: .utf8)
        try FileManager.default.setAttributes([.posixPermissions: 0o555], ofItemAtPath: configURL.deletingLastPathComponent().path)
        defer { try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: configURL.deletingLastPathComponent().path) }
        await #expect { try await setup().apply() } throws: { error in
            if case AeroSpaceSetup.SetupError.io = error { return true }
            return false
        }
    }

    @Test func loginShellRunnerFindsHomebrewAeroSpace() async {
        let installed = ["/opt/homebrew/bin/aerospace", "/usr/local/bin/aerospace"]
            .contains { FileManager.default.isExecutableFile(atPath: $0) }

        let result = await LoginShellAeroSpaceCLI().run(["--version"])

        #expect(result.status == (installed ? 0 : 127))
        if installed {
            #expect(result.output.contains("aerospace CLI client version"))
        }
    }

    static var timestamp: String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return formatter.string(from: Date(timeIntervalSince1970: 0))
    }
}
